with.command:
set -eu
printf '%s' "$TEXT" | REQUIRED="$REQUIRED" OPTIONAL="$OPTIONAL" python3 -c '
import json, os, re, subprocess, sys
try:
    asked = json.loads(sys.stdin.read())
except ValueError as error:
    sys.exit("the mandate is not one JSON object: %s" % error)
if not isinstance(asked, dict):
    sys.exit("the mandate is not one JSON object")
required = os.environ["REQUIRED"].split()
optional = json.loads(os.environ["OPTIONAL"])
missing = [key for key in required if not str(asked.get(key, "")).strip()]
if missing:
    sys.exit("the mandate does not name: " + ", ".join(missing))
unknown = sorted(set(asked) - set(required) - set(optional))
if unknown:
    sys.exit("the mandate names what this flow does not read: " + ", ".join(unknown))
out = {key: str(asked.get(key, default)) for key, default in optional.items()}
out.update({key: str(asked[key]) for key in required})
repo = out["repo"]
if not os.path.isabs(repo) or subprocess.run(["git", "-C", repo, "rev-parse", "--git-dir"], capture_output=True).returncode != 0:
    sys.exit("the repo is not an absolute path to a git tree: " + repo)
for key in ("branch", "base"):
    if key in out and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._/-]*", out[key]):
        sys.exit("the %s is not a plain branch name: %s" % (key, out[key]))
for key in ("issue",):
    if key in out and out[key] and not re.fullmatch(r"[0-9]+", out[key]):
        sys.exit("the issue is not a number: " + out[key])
if "version" in out and not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.]+)?", out["version"]):
    sys.exit("the version is not MAJOR.MINOR.PATCH: " + out["version"])
if "forge_repo" in out and out["forge_repo"] and not re.fullmatch(r"[A-Za-z0-9._-]+/[A-Za-z0-9._-]+", out["forge_repo"]):
    sys.exit("the forge_repo is not owner/name: " + out["forge_repo"])
print(json.dumps(out))
'

set -eu
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    token=$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$who") && [ -n "$token" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    if [ -n "${FORGE_REPO:-}" ]; then
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN GH_REPO="$FORGE_REPO" GH_TOKEN="$token" gh "$@"
    else
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN -u GH_REPO GH_TOKEN="$token" gh "$@"
    fi
}
printf '{"login":"%s"}' "$forge_as"

set -eu
# git ls-remote's own exit is checked before its answer is read: a lost transport is not an empty ref.
read_remote_ref() {
    listed=$(git -C "$REPO" ls-remote origin "$1") || { code=$?; echo "cannot read $1 on origin: git ls-remote exited $code, so nothing is decided on an empty answer" >&2; exit 2; }
    printf '%s\n' "$listed" | awk -v ref="$1" '$2 == ref { print $1 }'
}
commit=$(printf '%s' "$RECORDS" | python3 -c '
import json, sys
records = json.loads(sys.stdin.read())
if not records:
    sys.exit("no review of this branch is recorded: run review-a-pinned-commit first")
review = records[0]["value"]
if review.get("verdict") != "clean":
    sys.exit("the latest review of commit %s has findings: resolve them and review again" % review.get("commit"))
print(review["commit"])
')
git -C "$REPO" fetch --quiet origin
local_head=$(git -C "$REPO" rev-parse --verify "refs/heads/$BRANCH^{commit}" 2>/dev/null || true)
remote_head=$(read_remote_ref "refs/heads/$BRANCH")
[ "$local_head" = "$commit" ] || { echo "the branch head $local_head differs from the reviewed commit $commit: the review does not cover it" >&2; exit 1; }
[ "$remote_head" = "$commit" ] || { echo "the remote branch head ${remote_head:-nothing} differs from the reviewed commit $commit" >&2; exit 1; }
printf '{"commit":"%s"}' "$commit"

set -eu
cd "$REPO"
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    token=$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$who") && [ -n "$token" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    if [ -n "${FORGE_REPO:-}" ]; then
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN GH_REPO="$FORGE_REPO" GH_TOKEN="$token" gh "$@"
    else
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN -u GH_REPO GH_TOKEN="$token" gh "$@"
    fi
}
seen=$(forge pr view "$BRANCH" --json number,state,headRefOid,isDraft --jq '[.number, .state, .headRefOid, .isDraft] | @tsv')
number=$(printf '%s' "$seen" | cut -f1); state=$(printf '%s' "$seen" | cut -f2)
oid=$(printf '%s' "$seen" | cut -f3); draft=$(printf '%s' "$seen" | cut -f4)
[ "$oid" = "$COMMIT" ] || { echo "the pull request reads head $oid, not the reviewed $COMMIT" >&2; exit 1; }
case "$state" in OPEN|MERGED) ;; *) echo "the pull request is $state" >&2; exit 1 ;; esac
printf '{"number":%s,"state":"%s","draft":%s}' "$number" "$state" "$draft"

set -eu
# The policy is the file main commits, read here with git: a sailor found on PATH never decides who authorizes.
trusted_policy() {
    policy_commit=$(git -C "$REPO" rev-parse --verify --quiet "main^{commit}") || { echo "the trunk main does not exist in this tree: no trusted policy to read" >&2; exit 1; }
    policy_text=$(git -C "$REPO" show "$policy_commit:.sailor/delivery-policy.json") || { echo "main at $policy_commit carries no .sailor/delivery-policy.json" >&2; exit 1; }
    printf '%s' "$policy_text" | POLICY_COMMIT="$policy_commit" python3 -c '
import json, os, sys
def no_constant(name):
    raise ValueError("%s is not JSON" % name)
try:
    policy = json.loads(sys.stdin.read(), parse_constant=no_constant)
except ValueError as error:
    sys.exit("the delivery policy on main is not JSON: %s" % error)
if not isinstance(policy, dict):
    sys.exit("the delivery policy on main is not an object")
lines = []
for field in ("merge", "push", "release"):
    if policy.get(field) not in ("auto", "ask"):
        sys.exit("the delivery policy on main does not say auto or ask for %s" % field)
    lines.append("%s: %s" % (field, policy[field]))
lines.append(os.environ["POLICY_COMMIT"])
print("\n".join(lines))
'
}
cd "$REPO"
said=$(trusted_policy) || exit 1
printf '%s\n' "$said" | python3 -c '
import json, sys
lines = [line.strip() for line in sys.stdin if line.strip()]
fields = dict(line.split(": ", 1) for line in lines[:-1])
for key in ("merge", "push", "release"):
    if fields.get(key) not in ("auto", "ask"):
        sys.exit("the policy does not say auto or ask for " + key)
print(json.dumps({
    "merge": fields["merge"], "push": fields["push"], "release": fields["release"],
    "read_from": lines[-1],
    "asks_publication": "ask" if fields["push"] == "ask" else "auto",
    "asks_integration": "ask" if "ask" in (fields["merge"], fields["push"]) else "auto",
    "asks_release": "ask" if "ask" in (fields["release"], fields["push"]) else "auto",
}))
'

set -eu
# The policy is the file main commits, read here with git: a sailor found on PATH never decides who authorizes.
trusted_policy() {
    policy_commit=$(git -C "$REPO" rev-parse --verify --quiet "main^{commit}") || { echo "the trunk main does not exist in this tree: no trusted policy to read" >&2; exit 1; }
    policy_text=$(git -C "$REPO" show "$policy_commit:.sailor/delivery-policy.json") || { echo "main at $policy_commit carries no .sailor/delivery-policy.json" >&2; exit 1; }
    printf '%s' "$policy_text" | POLICY_COMMIT="$policy_commit" python3 -c '
import json, os, sys
def no_constant(name):
    raise ValueError("%s is not JSON" % name)
try:
    policy = json.loads(sys.stdin.read(), parse_constant=no_constant)
except ValueError as error:
    sys.exit("the delivery policy on main is not JSON: %s" % error)
if not isinstance(policy, dict):
    sys.exit("the delivery policy on main is not an object")
lines = []
for field in ("merge", "push", "release"):
    if policy.get(field) not in ("auto", "ask"):
        sys.exit("the delivery policy on main does not say auto or ask for %s" % field)
    lines.append("%s: %s" % (field, policy[field]))
lines.append(os.environ["POLICY_COMMIT"])
print("\n".join(lines))
'
}
# git ls-remote's own exit is checked before its answer is read: a lost transport is not an empty ref.
read_remote_ref() {
    listed=$(git -C "$REPO" ls-remote origin "$1") || { code=$?; echo "cannot read $1 on origin: git ls-remote exited $code, so nothing is decided on an empty answer" >&2; exit 2; }
    printf '%s\n' "$listed" | awk -v ref="$1" '$2 == ref { print $1 }'
}
cd "$REPO"
trusted_scan() {
    git -C "$REPO" show "main:scripts/privacy-scan.sh" 2>/dev/null | cmp -s - "$REPO/scripts/privacy-scan.sh" || { echo "scripts/privacy-scan.sh in this tree differs from the one the trusted trunk commits: the gate refuses to judge with it" >&2; exit 2; }
}
trusted_scan
policy_now=$(trusted_policy) || exit 1
policy_was=$(printf '%s' "$POLICY_READ" | python3 -c 'import json,sys; p=json.load(sys.stdin); print("merge: %s\npush: %s\nrelease: %s\n%s" % (p["merge"], p["push"], p["release"], p["read_from"]))')
[ "$policy_now" = "$policy_was" ] || { echo "the delivery policy changed since it was read: the authorization in flight no longer holds; run the flow again" >&2; exit 1; }
git fetch --quiet origin
trunk_now=$(git rev-parse --verify "refs/remotes/origin/$BASE^{commit}") || { echo "cannot read origin/$BASE after the fetch" >&2; exit 2; }
[ "$trunk_now" = "$BASE_COMMIT" ] || [ "$ALREADY" = true ] || { echo "the trunk moved since the combined tree was built on $BASE_COMMIT: run the integration again" >&2; exit 1; }
branch_now=$(git rev-parse --verify "refs/heads/$BRANCH^{commit}") || { echo "cannot read the branch $BRANCH" >&2; exit 2; }
[ "$branch_now" = "$COMMIT" ] || { echo "the branch head differs from the reviewed commit $COMMIT" >&2; exit 1; }
remote_head=$(read_remote_ref "refs/heads/$BRANCH")
[ "$ALREADY" = true ] || [ "$remote_head" = "$COMMIT" ] || { echo "the remote branch head ${remote_head:-nothing} differs from the reviewed commit $COMMIT: the pull request no longer shows what was reviewed" >&2; exit 1; }
set +e
if [ -n "$SCAN_BASE" ]; then "$REPO/scripts/privacy-scan.sh" "$REF" "$SCAN_BASE" >&2; else "$REPO/scripts/privacy-scan.sh" "$REF" >&2; fi
code=$?
set -e
[ "$code" -eq 0 ] || { echo "publication gate: privacy-scan exited $code on $REF; nothing leaves" >&2; exit "$code"; }
printf '{"ref":"%s","privacy_exit":0}' "$REF"

set -eu
cd "$REPO"
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    token=$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$who") && [ -n "$token" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    if [ -n "${FORGE_REPO:-}" ]; then
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN GH_REPO="$FORGE_REPO" GH_TOKEN="$token" gh "$@"
    else
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN -u GH_REPO GH_TOKEN="$token" gh "$@"
    fi
}
if [ "$DRAFT" = true ] && [ "$STATE" = OPEN ]; then
    forge pr ready "$NUMBER" >&2
fi
printf '{"number":%s}' "$NUMBER"

set -eu
url=$(git -C "$REPO" remote get-url origin) || { echo "the tree has no origin remote" >&2; exit 1; }
set -- -C "$REPO"
case "$url" in
    /*|file://*) ;;
    http://*|https://*)
        push_as=$(git -C "$REPO" config --get sailor.pushAs) || { echo "sailor.pushAs is not declared on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        [ -n "$push_as" ] || { echo "sailor.pushAs is empty on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        helper='!f() { printf "%s\\n" username=x-access-token; printf "password=%s\\n" "$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "'"$push_as"'")"; }; f'
        set -- -C "$REPO" -c credential.helper= -c "credential.helper=$helper" ;;
    *) echo "origin is $url: a push over it cannot be bound to sailor.pushAs, so this flow refuses it" >&2; exit 1 ;;
esac
if [ "$ALREADY" != true ]; then
    git "$@" push origin "$CANDIDATE:refs/heads/$BASE" >&2
fi
printf '{"pushed":"%s"}' "$CANDIDATE"

set -eu
git -C "$REPO" fetch --quiet origin
remote=$(git -C "$REPO" rev-parse "refs/remotes/origin/$BASE")
git -C "$REPO" merge-base --is-ancestor "$CANDIDATE" "$remote" || { echo "the remote $BASE at $remote does not carry $CANDIDATE" >&2; exit 1; }
git -C "$REPO" merge-base --is-ancestor "$COMMIT" "$remote" || { echo "the remote $BASE at $remote does not carry the reviewed $COMMIT" >&2; exit 1; }
printf '{"remote_trunk":"%s"}' "$remote"
